// include/monst.h — pmnames indices
export const MALE = 0, FEMALE = 1, NEUTRAL = 2;

export function mons_name(pm) {
    return pm.pmnames[NEUTRAL] ?? pm.pmnames[MALE] ?? pm.pmnames[FEMALE];
}
